import { Quat, Vec3 } from 'playcanvas';
export class SplatControls {
  getPose(){return{position:[this.position.x,this.position.y,this.position.z],target:[this.target.x,this.target.y,this.target.z],up:[this.up.x,this.up.y,this.up.z],fov:this.camera.camera.fov};}
  constructor(canvas,camera,onInteract){this.canvas=canvas;this.camera=camera;this.onInteract=onInteract;this.pointers=new Map();this.abort=new AbortController();const o={signal:this.abort.signal};canvas.addEventListener('pointerdown',e=>this.down(e),o);canvas.addEventListener('pointermove',e=>this.move(e),o);for(const k of ['pointerup','pointercancel'])canvas.addEventListener(k,e=>{this.pointers.delete(e.pointerId);this.lastPinch=null;},o);canvas.addEventListener('contextmenu',e=>e.preventDefault(),o);canvas.addEventListener('keydown',e=>{const directions={ArrowLeft:[-14,0],ArrowRight:[14,0],ArrowUp:[0,-14],ArrowDown:[0,14]};if(!directions[e.key]&&!['+','=','-'].includes(e.key))return;e.preventDefault();this.onInteract();if(directions[e.key])this.rotate(...directions[e.key]);else this.zoom(e.key==='-'?1.1:.9);},o);canvas.addEventListener('wheel',e=>{e.preventDefault();this.onInteract();this.zoom(Math.exp(Math.max(-180,Math.min(180,e.deltaY))*.0015));},{...o,passive:false});}
  setPose(p){this.position=new Vec3(...p.position);this.target=new Vec3(...p.target);this.up=new Vec3(...(p.up??[0,1,0])).normalize();this.distance=this.position.clone().sub(this.target).length();this.minDistance=Math.max(.001,this.distance*.025);this.maxDistance=this.distance*12;this.camera.camera.fov=p.fov??52;this.apply();}
  apply(){this.camera.setPosition(this.position);this.camera.lookAt(this.target,this.up);const d=this.position.clone().sub(this.target).length();this.camera.camera.nearClip=Math.max(.0001,d*.001);this.camera.camera.farClip=Math.max(d*100,10000);}
  rotate(dx,dy){if(!this.position)return;let offset=this.position.clone().sub(this.target);offset=new Quat().setFromAxisAngle(this.up,-dx*.22).transformVector(offset);const forward=offset.clone().normalize(),right=new Vec3().cross(this.up,forward).normalize();const next=new Quat().setFromAxisAngle(right,-dy*.22).transformVector(offset);if(Math.abs(next.clone().normalize().dot(this.up))<.985)offset=next;this.position.copy(this.target).add(offset);this.apply();}
  pan(dx,dy){if(!this.position)return;const forward=this.target.clone().sub(this.position).normalize(),right=new Vec3().cross(forward,this.up).normalize(),vertical=new Vec3().cross(right,forward).normalize();const distance=this.position.clone().sub(this.target).length(),scale=2*distance*Math.tan(this.camera.camera.fov*Math.PI/360)/Math.max(1,this.canvas.clientHeight);const delta=right.mulScalar(-dx*scale).add(vertical.mulScalar(dy*scale));this.position.add(delta);this.target.add(delta);this.apply();}
  zoom(factor){if(!this.position)return;const offset=this.position.clone().sub(this.target),distance=Math.max(this.minDistance,Math.min(this.maxDistance,offset.length()*factor));this.position.copy(this.target).add(offset.normalize().mulScalar(distance));this.apply();}
  down(e){if(!this.position)return;this.onInteract();this.canvas.setPointerCapture(e.pointerId);this.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY,pan:e.button!==0||e.shiftKey});this.lastPinch=null;}
  move(e){const previous=this.pointers.get(e.pointerId);if(!previous)return;const current={x:e.clientX,y:e.clientY,pan:previous.pan};this.pointers.set(e.pointerId,current);if(this.pointers.size===2){const [a,b]=[...this.pointers.values()],pinch={distance:Math.hypot(a.x-b.x,a.y-b.y),x:(a.x+b.x)/2,y:(a.y+b.y)/2};if(this.lastPinch){this.zoom(this.lastPinch.distance/Math.max(1,pinch.distance));this.pan(pinch.x-this.lastPinch.x,pinch.y-this.lastPinch.y);}this.lastPinch=pinch;}else{this.lastPinch=null;(current.pan?this.pan:this.rotate).call(this,current.x-previous.x,current.y-previous.y);}}
  destroy(){this.abort.abort();this.pointers.clear();}
}
